"<style>
 @import url('https://fonts.googleapis.com/css2?family=Roboto+Mono:ital,wght@0,100..700;1,100..700&family=Roboto:ital,wght@0,100;0,300;0,400;0,500;0,700;0,900;1,100;1,300;1,400;1,500;1,700;1,900&display=swap');

 #container { 
 min-width: 300px !important; 
 }

 #container * {
 font-family: "Roboto", sans-serif;
 text-align: center;
 }

 #container .cih-box {
 border-radius: 4px;
 box-shadow: rgba(0, 0, 0, 0.12) 0px 1px 3px, rgba(0, 0, 0, 0.24) 0px 1px 2px;
 }

 #container .cih-flex-row {
 display: flex;
 flex-direction: row;
 align-items: center;
 justify-content: space-between;
 }

 #container .cih-flex-col {
 display: flex;
 flex-direction: column;
 }

 #container .cih-flex-inline {
 display: inline-flex;
 align-items: center;
 justify-content: start;
 }

 #container .cih-flex-inline > *:not(:first-child) {
 margin-left: 5px;
 }

 #container .cih-sticky {
 position: sticky;
 top: 0;
 z-index: 1;
 background-color: #fff;
 align-items: top;
 border-bottom: 1px solid #ccc;
 }

 #container .cih-select {
 outline: 1px solid #ccc;
 border: none;
 background-color: #f7fafc;
 cursor: pointer;

 padding-top: 5px;
 padding-bottom: 5px;
 padding-left: 10px;
 padding-right: 5px;
 border-radius: 20px;
 margin-top: 15px;
 border-right: 10px solid transparent;
 width: 100%;
 transition: 0.2s;
 text-align: left;
 text-align-last: left;
 }

 #container .cih-select:hover {
 background-color: #e2eef3;
 }

 #container .cih-select option[disabled] {
 display: none;
 }

 #container .cih-anchor {
 text-decoration: none;
 color: #0f206c;
 transition: 0.2s;
 }

 #container .cih-anchor:hover {
 color: #acc74f;
 }

 #container .cih-expand {
 -webkit-user-select: none;
 -moz-user-select: none;
 -ms-user-select: none;
 user-select: none;
 }

 #container .cih-expand svg {
 transition: 0.2s;
 }

 #container .cih-expand input[type="checkbox"] {
 position: absolute;
 opacity: 0;
 cursor: pointer;
 }

 #container .cih-expand:has(input[type="checkbox"]:checked) svg {
 transform: rotate(0deg) !important;
 }

 #container
 .cih-com-row:has(.cih-expand input[type="checkbox"]:checked)
 .cih-table {
 display: none;
 }


 #container .cih-loc-card > .cih-com-row {
 border-top: 1px solid #ccc;
 }


 #container .cih-table {
 border-collapse: collapse;
 margin: 10px;
 }

 #container .cih-table > thead > tr {
 font-size: 12px;
 }

 #container .cih-table > tbody > tr {
 font-size: 14px;
 text-align: center;
 border-top: 1px solid #ccc;
 }

 #container .cih-table tr > th,
 #container .cih-table tr > td {
 padding: 5px;
 }

 #container .cih-table tr > th:nth-child(1),
 #container .cih-table tr > td:nth-child(1) {
 text-align: left;
 }

 #container .cih-table tr > th:nth-child(n+3):nth-child(-n+6),
 #container .cih-table tr > td:nth-child(n+3):nth-child(-n+6) {
 text-align: right;
 }

 #container .cih-table tr > td:nth-child(1) {
 width: 25% !important;
 }

 #container .cih-table tr > td:nth-child(2) {
 width: 30% !important
 }

 #container .cih-table tr > td:nth-child(3) {
 width: 17%;
 }

 #container .cih-table tr > td:nth-child(4),
 #container .cih-table tr > td:nth-child(5) {
 width: 13%;
 }

 #container .cih-table tr > td:nth-child(2) > div {
 max-width: 125px;
 margin: auto;
 }
 #container .cih-table tr > td:nth-child(3) > div {
 margin-left: auto;
 max-width: 60px;
 }

 #container .cih-table tr > td:nth-child(2) > div > span:first-child,
 #container .cih-table tr > td:nth-child(3) > div > span:first-child {
 flex: 1;
 text-align: left;
 }

 #container .cih-table tr > td:nth-child(2) > div > span:last-child, 
 #container .cih-table tr > td:nth-child(3) > div > span:last-child {
 flex: 1;
 text-align: right;
 }

 #container .cih-table .change > span:last-child {
 display: inline-block;
 }

 #container .cih-table .change svg {
 display: none;
 }

 #container .cih-table .change.positive {
 color: #48bb78;
 }

 #container .cih-table .change.positive svg {
 display: inline-block !important;
 }

 #container .cih-table .change.negative {
 color: #f56565;
 }

 #container .cih-table .change.negative svg {
 display: inline-block !important;
 transform: rotate(180deg);
 }

 #cih-popup {
 position: fixed;
 top: 0;
 left: 0;
 height: 100%;
 width: 100%;
 z-index: 100;
 display: flex;
 justify-content: center;
 align-items: center;
 background-color: rgba(0, 0, 0, 0.5);
 }

 #cih-popup > div {
 background-color: rgba(255, 255, 255, 1);
 }

 #cih-popup > div > div:first-child {
 background-color: #f7fafc;
 }

 #cih-popup .cih-loading-container {
 display: none;
 }

 #cih-popup.cih-loading .cih-loading-container,
 #cih-popup #cih-popup-chart {
 padding: 5px;
 flex: 1;
 }

 #cih-popup #cih-popup-chart {
 position: relative;
 min-height: 400px;
 }

 #cih-popup #cih-popup-content {
 width: 95%;
 min-height: 500px;
 }

 #cih-popup #cih-popup-content > div:first-child {
 border-bottom: 1px solid #ccc;
 border-radius: 4px 4px 0 0;
 }

 #container .cih-hide {
 display: none !important;
 }

 #container .cih-clickable {
 cursor: pointer;
 }

 #container .cih-clickable > * {
 pointer-events: none;
 }

 #container .cih-r-180 {
 transform: rotate(180deg);
 }

 #container .cih-svg-large {
 height: 18px;
 }

 #container .cih-svg-medium {
 height: 16px;
 }

 #container .cih-svg-small {
 height: 12px;
 }

 #container .cih-svg-tiny {
 height: 10px;
 }

 #container .cih-text-large {
 font-size: 18px;
 }

 #container .cih-text-medium {
 font-size: 16px;
 }

 #container .cih-text-small {
 font-size: 14px;
 }

 #container .cih-text-tiny {
 font-size: 12px;
 }

 #container .cih-p-20 {
 padding: 10px;
 }

 #container .cih-m-b-20 {
 margin-bottom: 20px;
 }

 #container .cih-sep-v {
 margin: 0 5px;
 height: 10px;
 border-right: 1px solid #ccc;
 }

 @media screen and (max-width: 450px) {
 #container .cih-table {
 margin: 5px;
 }

 #container .cih-table > tbody > tr {
 font-size: 12px;
 }

 #container .cih-table tr > th,
 #container .cih-table tr > td {
 padding: 10px 0;
 }

 #container .cih-table tr > td:nth-child(2) > div {
 width: 100px;
 }

 #container .cih-table tr > td:nth-child(3) > div {
 width: 50px;
 }

 #container .cih-svg-medium {
 height: 12px;
 width: 12px;
 }

 #container .cih-text-small {
 font-size: 12px;
 }

 #container .cih-text-tiny {
 font-size: 10px;
 }

 #container .cih-sep-v {
 height: 15px;
 }

 #container .cih-select {
 margin-left: 0;
 margin-top: 15px;
 border-right: 5px solid transparent;
 padding-top: 10px;
 padding-bottom: 10px;
 font-size: 14px;
 }
 }

 @media screen and (max-width: 400px) {
 #container .cih-table .cih-chart-btn > span:first-child {
 display: none !important;
 }

 #container .cih-table .change svg,
 #container .cih-table .change.positive svg,
 #container .cih-table .change.negative svg {
 display: none !important;
 }
 }
